"""Compiled engine: wide-signal external I/O matrix (@pytest.mark.slow).

Split mechanically from tests/test_sim/test_compiled.py (work plan item 2.5).
"""

from __future__ import annotations

from ._shared import *  # noqa: F401,F403


@pytest.mark.slow
class TestWideSignalExternalIO:
    """Validate compiled external signal access for widths beyond 64 bits.

    This class contains ~3800 parametrized tests and is tagged ``slow``.
    It is skipped by default; pass ``--run-slow`` to include it.
    """

    @staticmethod
    def _repeat_value(value: int, width: int, count: int) -> Value:
        repeated = 0
        for _ in range(count):
            repeated = (repeated << width) | value
        return Value(repeated, width=width * count)

    @pytest.mark.parametrize(
        ("width", "value"),
        [
            (65, (1 << 64) | 0x1234),
            (129, (1 << 128) | (0xFEDCBA9876543210 << 32) | 0x12345678),
        ],
    )
    def test_drive_and_read_wide_signal_cross_engine(self, width, value):
        results = {}
        for eng in ["reference", "vm", "compiled"]:
            sim = Simulator(_make_wide_signal_shell(width), engine=eng)
            sim.drive("sig", Value(value, width=width))
            results[eng] = sim.read("sig")

        ref = results["reference"]
        for eng in ["vm", "compiled"]:
            assert results[eng] == ref, f"{eng}: {results[eng]} != {ref}"

    @pytest.mark.parametrize("width", [65, 129])
    def test_compiled_eval_context_wide_signal_round_trip(self, width):
        value = (1 << (width - 1)) | 0x5A5A
        sim = Simulator(_make_wide_signal_shell(width), engine="compiled")
        sim._sched.ctx.write_signal("sig", Value(value, width=width))
        assert sim._sched.ctx.read_signal("sig") == Value(value, width=width)

