    def test_transport_only_mode_keeps_wide_seq_concat_pair(self, monkeypatch):
        monkeypatch.setenv("VERIFORGE_COMPILED_WIDE_TRANSPORT_ONLY", "1")

        results = {}
        for eng in ["reference", "vm", "compiled"]:
            sim = Simulator(_make_wide_seq_concat_pair(65, 64, 129), engine=eng)
            sim.drive("hi", Value((1 << 64) | 0x1555, width=65))
            sim.drive("lo", Value(0x0FEDCBA987654321, width=64))
            sim.drive("q", Value(0, width=129))
            clk = Clock(sim.signal("clk"), period=10)
            sim.fork(clk)
            sim._schedule_clock_events(clk, 40)
            for _ in range(2):
                sim.run_step()
            results[eng] = sim.read("q")

        expected = _pack_concat_parts(
            [
                ("hi", Value((1 << 64) | 0x1555, width=65)),
                ("lo", Value(0x0FEDCBA987654321, width=64)),
            ]
        )
        assert results["reference"] == expected
        assert results["compiled"] == results["reference"]
        assert results["vm"] == results["reference"]

    @pytest.mark.parametrize(
        ("builder", "needs_clock"),
        [
            (_make_wide_struct_assignment_pattern_cont, False),
            (_make_wide_struct_assignment_pattern_combo, False),
            (_make_wide_struct_assignment_pattern_seq, True),
        ],
    )
    def test_transport_only_mode_keeps_wide_struct_assignment_pattern(self, monkeypatch, builder, needs_clock):
        monkeypatch.setenv("VERIFORGE_COMPILED_WIDE_TRANSPORT_ONLY", "1")

        data_value = (1 << 64) | 0x13579BDF
        valid_value = 1
        results = {}
        for eng in ["reference", "vm", "compiled"]:
            sim = Simulator(builder(), engine=eng)
            sim.drive("in_data", Value(data_value, width=65))
            sim.drive("in_valid", Value(valid_value, width=1))
            if needs_clock:
                clk = Clock(sim.signal("clk"), period=10)
                sim.fork(clk)
                sim._schedule_clock_events(clk, 40)
                for _ in range(2):
                    sim.run_step()
            else:
                sim.run(max_time=0)
            results[eng] = {
                "out_bus": sim.read("out_bus"),
                "out_data": sim.read("out_data"),
                "out_valid": sim.read("out_valid"),
            }

        assert results["reference"]["out_data"] == Value(data_value, width=65)
        assert results["reference"]["out_valid"] == Value(valid_value, width=1)
        assert results["compiled"] == results["reference"]
        assert results["vm"] == results["reference"]

