    @pytest.mark.parametrize(
        ("builder_name", "needs_clock"),
        [
            ("_make_wide_struct_signal_field_read_cont", False),
            ("_make_wide_struct_signal_field_read_combo", False),
            ("_make_wide_struct_signal_field_read_seq", True),
        ],
    )
    def test_transport_only_mode_keeps_wide_struct_signal_field_read(self, monkeypatch, builder_name, needs_clock):
        monkeypatch.setenv("VERIFORGE_COMPILED_WIDE_TRANSPORT_ONLY", "1")

        builder = globals()[builder_name]
        data_value = (1 << 64) | 0x13579BDF2468ACE
        data_mask = 0x24
        valid_value = 1
        valid_mask = 1
        results = {}
        for eng in ["reference", "vm", "compiled"]:
            sim = Simulator(builder(), engine=eng)
            sim.drive("in_data", Value(data_value, width=65, mask=data_mask))
            sim.drive("in_valid", Value(valid_value, width=1, mask=valid_mask))
            if needs_clock:
                clk = Clock(sim.signal("clk"), period=10)
                sim.fork(clk)
                sim._schedule_clock_events(clk, 40)
                for _ in range(2):
                    sim.run_step()
            else:
                sim.run(max_time=0)
            results[eng] = {
                "out_bus": sim.read("out_bus"),
                "out_data": sim.read("out_data"),
                "out_valid": sim.read("out_valid"),
            }

        expected_bus = Value(
            ((data_value & ~data_mask) << 1) | (valid_value & ~valid_mask), width=66, mask=(data_mask << 1) | valid_mask
        )
        expected_data = Value(data_value, width=65, mask=data_mask)
        expected_valid = Value(valid_value, width=1, mask=valid_mask)
        assert results["reference"]["out_bus"] == expected_bus
        assert results["reference"]["out_data"] == expected_data
        assert results["reference"]["out_valid"] == expected_valid
        assert results["compiled"] == results["reference"]
        assert results["vm"] == results["reference"]

