    @pytest.mark.parametrize(
        ("src_width", "shift_value", "value"),
        [
            (65, 4, (1 << 64) | 0x123456789ABCDEF0),
            (129, 68, (1 << 128) | (0x89ABCDEF01234567 << 32) | 0x2468ACE0),
        ],
    )
    def test_wide_seq_signed_shift_var_binop_cross_engine(self, src_width, shift_value, value):
        results = {}
        for eng in ["vm", "compiled"]:
            sim = Simulator(_make_wide_seq_signed_shift_var_binop(src_width), engine=eng)
            sim.drive("a", Value(value, width=src_width))
            sim.drive("sh", Value(shift_value, width=8))
            sim.drive("q", Value(0, width=src_width))
            clk = Clock(sim.signal("clk"), period=10)
            sim.fork(clk)
            sim._schedule_clock_events(clk, 40)
            for _ in range(2):
                sim.run_step()
            results[eng] = sim.read("q")

        assert results["compiled"] == results["vm"], f"compiled: {results['compiled']} != {results['vm']}"

